  if(NGECHI_ADV.test(w)) return {root:w,m:[],wclass:'adverb',nvRule:'ngechi adverb'};
  if(NV_WHOLE[w]) return {root:w,m:[],wclass:NV_WHOLE[w],nvRule:'lexicon'};
  /* demonstrative adverbs with mu/mew/meu written on: ta-meu, fey-ti-mu, tiy-mu (annotation); fey-mu by analogy (unruled) */
  /* build110: tüfa mu is two words (analyst ruling 2026-10-27); fey-mu, fey-ti-mu, ta-meu, tiy-mu stay adverbs */
  let mm=/^(ta|tiy|fey|vey)(ti)?(mu|mew|meu)$/.exec(w);
  if(mm) return {root:mm[1],m:(mm[2]?[nvm(mm[2],'DEM')]:[]).concat([nvm(mm[3],'ADV')]),wclass:'adverb',nvRule:'dem+mu'};
